// A fake Dropbox of the model for `DEV_FAKE_SOURCE=1 pnpm dev:server` (SPEC §12.0: external
// systems are fake servers in development too). Media is generated by FFmpeg — test patterns,
// fractals and gradients, no people — so «Приехало» shows real pictures. Read-only like the
// real one. Started by `dev-stack.mjs`; prints `ready <url>` when it listens.
import { execFileSync } from 'node:child_process'
import { mkdtempSync, readFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { FakeDropbox, FakeTree } from '@contentops/sources/testing'

const PORT = Number(process.env.DEV_SOURCE_PORT ?? '54330')
const TOKEN = process.env.DEV_SOURCE_TOKEN ?? 'dev-dropbox-token'
const work = mkdtempSync(join(tmpdir(), 'contentops-dev-source-'))

function ffmpeg(args: string[]): void {
  execFileSync('ffmpeg', ['-v', 'error', '-y', ...args], { stdio: 'inherit' })
}

/** A photo: one frame of a generated pattern, 1080×1440. */
function photo(name: string, source: string): Buffer {
  const out = join(work, `${name}.jpg`)
  ffmpeg(['-f', 'lavfi', '-i', `${source}=size=1080x1440`, '-frames:v', '1', '-q:v', '3', out])
  return readFileSync(out)
}

/** A short vertical video with a tone, and its poster. */
function video(name: string, source: string, seconds: number): { bytes: Buffer; poster: Buffer } {
  const out = join(work, `${name}.mp4`)
  ffmpeg([
    '-f', 'lavfi', '-i', `${source}=size=720x1280:rate=30`,
    '-f', 'lavfi', '-i', `sine=frequency=330:duration=${seconds}`,
    '-t', String(seconds), '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-c:a', 'aac', '-shortest', out,
  ])
  const poster = join(work, `${name}.poster.jpg`)
  ffmpeg(['-i', out, '-frames:v', '1', '-vf', 'scale=480:-2', '-q:v', '4', poster])
  return { bytes: readFileSync(out), poster: readFileSync(poster) }
}

const tree = new FakeTree({ caseInsensitive: true, idPrefix: 'id:dev_' })
const thumbs = new Map<string, Buffer>()
const minutesAgo = (minutes: number) => new Date(Date.now() - minutes * 60_000)

const patterns = ['mandelbrot', 'cellauto', 'life', 'testsrc2', 'gradients', 'smptehdbars']
for (let n = 1; n <= 6; n++) {
  const bytes = photo(`set-${n}`, patterns[n - 1] as string)
  const node = tree.addFile(`/4. Sets/Утро у окна/IMG_${4100 + n}.jpg`, bytes, {
    created: minutesAgo(40 - n),
    modified: minutesAgo(40 - n),
  })
  thumbs.set(node.id, bytes)
}
for (const [index, [name, source, seconds]] of (
  [
    ['12:40 в красном', 'testsrc2', 6],
    ['08:15 йога', 'gradients', 4],
  ] as const
).entries()) {
  const clip = video(`custom-${index}`, source, seconds)
  const node = tree.addFile(`/3. Customs/${name}.mp4`, clip.bytes, {
    created: minutesAgo(25 - index),
    modified: minutesAgo(25 - index),
  })
  thumbs.set(node.id, clip.poster)
}
const life = video('life', 'cellauto', 5)
const lifeNode = tree.addFile('/6. Life/завтрак.mp4', life.bytes, {
  created: minutesAgo(12),
  modified: minutesAgo(12),
})
thumbs.set(lifeNode.id, life.poster)
for (let n = 1; n <= 3; n++) {
  const bytes = photo(`raw-${n}`, patterns[(n + 2) % patterns.length] as string)
  const node = tree.addFile(`/8. Other/IMG_${5200 + n}.jpg`, bytes, {
    created: minutesAgo(8 - n),
    modified: minutesAgo(8 - n),
  })
  thumbs.set(node.id, bytes)
}

const server = await new FakeDropbox({
  token: TOKEN,
  tree,
  thumbnail: (node) => thumbs.get(node.id) ?? null,
}).start(PORT)
console.log(`ready ${server.url}`)
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    server.close().finally(() => process.exit(0))
  })
}
